      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : AddCommMonoid α] [inst_1 : TopologicalSpace α] {β : Type u_4} [inst_2 : InvolutiveNeg β]\n  (f : β → α), ∑' (d : β), f (-d) = ∑' (d : β), f d"
    },
    {
