      "module_name": "Mathlib.Algebra.Polynomial.Smeval",
      "kind": "theorem",
      "type": "∀ (R : Type u_1) [inst : Ring R] {S : Type u_2} [inst_1 : AddCommGroup S] [inst_2 : Pow S ℕ] [inst_3 : Module R S]\n  (p : Polynomial R) (x : S), (-p).smeval x = -p.smeval x"
    },
    {
      "name": "Polynomial.roots_neg",
      "module_name": "Mathlib.Algebra.Polynomial.Roots",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] [inst_1 : IsDomain R] (p : Polynomial R), (-p).roots = p.roots"
    },
